-- Check constraints
ALTER TABLE ultimateteam.clubs
    ADD CONSTRAINT lfv4_ck_clubs_balances CHECK (credits >= 0 AND fifa_points >= 0);
ALTER TABLE ultimateteam.items
    ADD CONSTRAINT lfv4_ck_items_native_positive CHECK (native_item_id > 0);
ALTER TABLE ultimateteam.consumable_items
    ADD CONSTRAINT lfv4_ck_consumable_items_quantities CHECK (quantity > 0 AND untradeable_quantity >= 0 AND untradeable_quantity <= quantity);
ALTER TABLE ultimateteam.player_stat_values
    ADD CONSTRAINT lfv4_ck_player_stat_values_stat_bounds CHECK (scope IN ('current', 'lifetime') AND stat_index >= 0 AND stat_index < 5 AND value >= 0);
ALTER TABLE ultimateteam.market_player_stat_values
    ADD CONSTRAINT lfv4_ck_market_player_stat_values_stat_bounds CHECK (scope IN ('current', 'lifetime') AND stat_index >= 0 AND stat_index < 5 AND value >= 0);
ALTER TABLE ultimateteam.squad_players
    ADD CONSTRAINT lfv4_ck_squad_players_slot_bounds CHECK (slot_index >= 0 AND slot_index < 23);
ALTER TABLE ultimateteam.squad_players
    ADD CONSTRAINT lfv4_ck_squad_players_reference_kind CHECK ((reference_kind = 'owned' AND item_id IS NOT NULL AND concept_wire_id IS NULL) OR (reference_kind = 'concept' AND item_id IS NULL AND concept_wire_id IS NOT NULL));
ALTER TABLE ultimateteam.squad_managers
    ADD CONSTRAINT lfv4_ck_squad_managers_reference_kind CHECK ((reference_kind = 'owned' AND item_id IS NOT NULL) OR (reference_kind = 'verified preview' AND item_id IS NULL));
ALTER TABLE ultimateteam.club_slot_bindings
    ADD CONSTRAINT lfv4_ck_club_slot_bindings_reference_kind CHECK ((reference_kind = 'owned' AND item_id IS NOT NULL) OR (reference_kind = 'verified virtual default' AND item_id IS NULL));
ALTER TABLE ultimateteam.squad_tactic_settings
    ADD CONSTRAINT lfv4_ck_squad_tactic_settings_one_typed_value CHECK (num_nonnulls(integer_value, boolean_value, text_value) = 1);
ALTER TABLE ultimateteam.squad_tactic_instructions
    ADD CONSTRAINT lfv4_ck_squad_tactic_instructions_one_typed_value CHECK (num_nonnulls(integer_value, text_value) = 1);
ALTER TABLE ultimateteam.market_listings
    ADD CONSTRAINT lfv4_ck_market_listings_kind_seller CHECK ((kind = 'player' AND seller_club_id IS NOT NULL AND seller_item_id IS NOT NULL AND seller_item_id > 0) OR (kind = 'ai' AND seller_club_id IS NULL AND seller_item_id IS NULL));
ALTER TABLE ultimateteam.market_listings
    ADD CONSTRAINT lfv4_ck_market_listings_state CHECK (state IN ('active', 'closed', 'expired', 'cancelled'));
ALTER TABLE ultimateteam.market_listings
    ADD CONSTRAINT lfv4_ck_market_listings_amounts CHECK (starting_bid >= 0 AND buy_now >= starting_bid AND current_bid >= 0 AND sold_price >= 0 AND offers >= 0);
ALTER TABLE ultimateteam.market_listings
    ADD CONSTRAINT lfv4_ck_market_listings_active_bid CHECK (state <> 'active' OR current_bid = 0 OR bidder_club_id IS NOT NULL);
ALTER TABLE ultimateteam.market_listings
    ADD CONSTRAINT lfv4_ck_market_listings_active_times CHECK (state <> 'active' OR end_time > created_at);
ALTER TABLE ultimateteam.objective_claims
    ADD CONSTRAINT lfv4_ck_objective_claims_scope CHECK (scope IN ('level', 'objective', 'group'));
ALTER TABLE ultimateteam.onboarding_kit_choices
    ADD CONSTRAINT lfv4_ck_onboarding_kit_choices_role CHECK (role IN ('home', 'away'));
